            if msgs:
                bad += 1
        finally:
            shutil.rmtree(tmp, ignore_errors=True)
    if bad:
        print(f"{bad} of {len(SPEC['cases'])} hidden cases failed")
        sys.exit(1)
    print(f"ok: {len(SPEC['cases'])} cases")


main()
